<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><section class="list-head"><div><p>Content manager</p><h1><?= empty($row) ? 'New ' : 'Edit ' ?><?= esc(rtrim($meta['label'], 's')) ?></h1></div><a href="<?= site_url('admin/' . $entity) ?>">← Back to <?= strtolower($meta['label']) ?></a></section><form class="editor-form" method="post" action="<?= empty($row) ? site_url('admin/' . $entity) : site_url('admin/' . $entity . '/' . $row['id']) ?>"><?= csrf_field() ?><?php foreach ($meta['fields'] as $name => $type): ?><label class="<?= in_array($type, ['textarea', 'richtext']) ? 'wide' : '' ?>"><?= esc(ucwords(str_replace('_', ' ', $name))) ?><?php if ($type === 'textarea' || $type === 'richtext'): ?><textarea name="<?= esc($name) ?>" rows="<?= $type === 'richtext' ? 12 : 5 ?>"><?= esc(old($name, $row[$name] ?? '')) ?></textarea><?php elseif ($type === 'status' || $type === 'inquiry_status'): ?><select name="<?= esc($name) ?>"><?php foreach ($type === 'inquiry_status' ? ['new', 'in_progress', 'resolved'] : ['draft', 'published'] as $option): ?><option value="<?= $option ?>" <?= old($name, $row[$name] ?? '') === $option ? 'selected' : '' ?>><?= ucwords(str_replace('_', ' ', $option)) ?></option><?php endforeach ?></select><?php else: ?><input type="<?= $type === 'datetime' ? 'datetime-local' : $type ?>" name="<?= esc($name) ?>" value="<?= esc($type === 'datetime' && ! empty($row[$name]) ? date('Y-m-d\TH:i', strtotime($row[$name])) : old($name, $row[$name] ?? '')) ?>"><?php endif ?></label><?php endforeach ?><div class="form-actions"><button class="primary" type="submit">Save <?= esc(rtrim($meta['label'], 's')) ?></button></div></form><?= $this->endSection() ?>
